function (vars) {
	var c = new ReadOnlyDetailView(vars.element);
	c.title = "#:Credit.types[CreditTypeId-1].name# \\##:Number# [resource_shortdisplayname[from]]: #:CreditorName# [resource_shortdisplayname[to]] #:DebtorName#";
	// optional, but we want a subset of fields here so lets be explicit.
	c.fields = [
		{ field: "Number", title: "[resource_shortdisplayname[Number]]", description: "[resource_description[Number]]" },
		{ field: "DebtorName", title: "[resource_shortdisplayname[DebtorName]]", description: "[resource_description[DebtorName]]" },
		{ field: "DebtorState", template: "#:B2B.transactionStates[DebtorState]#", title: "[resource_shortdisplayname[DebtorState]]", description: "[resource_description[DebtorState]]" },
		{ field: "DebtorExternalState", template: "#:(DebtorExternalState != null ? B2B.transactionStates[DebtorExternalState] : '')#", title: "[resource_shortdisplayname[DebtorExternalState]]", description: "[resource_description[DebtorExternalState]]" },
		{ field: "SourceSystemId", title: "[resource_shortdisplayname[sourcesystemid]]", description: "[resource_description[sourcesystemid]]" },
		{ field: "CreditorName", title: "[resource_shortdisplayname[CreditorName]]", description: "[resource_description[CreditorName]]" },
		{ field: "CreditorState", template: "#:B2B.transactionStates[CreditorState]#", title: "[resource_shortdisplayname[CreditorState]]", description: "[resource_description[CreditorState]]" },
		{ field: "CreditorExternalState", title: "[resource_shortdisplayname[CreditorExternalState]]", description: "[resource_description[CreditorExternalState]]", template: "#:(CreditorExternalState != null ? B2B.transactionStates[CreditorExternalState] : '')#" },
		{ field: "FundingState", template: "#= (FundingState) ? B2B.transactionStates[FundingState]: '' #" , title: "[resource_shortdisplayname[FundingState]]", description: "[resource_description[FundingState]]" },
		{ field: "FunderExternalState", title: "[resource_shortdisplayname[FunderExternalState]]", description: "[resource_description[FunderExternalState]]", template: "#:(FunderExternalState != null ? B2B.transactionStates[FunderExternalState] : '')#" },
		{ field: "CreationDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[CreationDate]]", description: "[resource_description[CreationDate]]" },
		{ field: "ReceivedDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[ReceivedDate]]", description: "[resource_description[ReceivedDate]]" },
		{ field: "DueDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[DueDate]]", description: "[resource_description[DueDate]]" },
		{ field: "DebtorPaymentDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[BuyerPaymentDate]]", description: "[resource_description[BuyerPaymentDate]]" },
		{ field: "LastUpdated", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[LastUpdated]]", description: "[resource_description[LastUpdated]]" },
		{ field: "TaxPoint", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[TaxPoint]]", description: "[resource_description[TaxPoint]]" },
		{ field: "ValueOfTax", type: "number", format: type.moneyFormat, title: "[resource_shortdisplayname[ValueOfTax]]", description: "[resource_description[ValueOfTax]]" },
		{ field: "Value", type: "number", format: type.moneyFormat, title: "[resource_shortdisplayname[Value]]", description: "[resource_description[Value]]" }
	];
    c.splits = ["CreationDate"];
    c.toolbar = "<button onClick='javascript: history.go(-1)'><span class='k-icon k-i-arrow-parent'></span> [resource_shortdisplayname[back]]</button>";
	vars.CreditDetails = c;
}
